uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;

attribute vec3 aPosition;
attribute vec2 aTexCoord;
varying vec2 vTexCoord;
varying float vWave;

uniform float uTime;

${snoise}

void main() {
  vTexCoord = aTexCoord;

  vec3 noisePos = vec3(aTexCoord.x * 50.0, aTexCoord.y * 234.0, uTime);
  float wave = snoise(noisePos); 
  vWave = wave;

  vec4 positionVec4 = vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
}
`

let frag = /* glsl */ `
precision mediump float;
uniform sampler2D uTex;
uniform float uTime;
varying vec2 vTexCoord;

${snoise}

void main() {
  vec2 st = vTexCoord;
  float angle = 1.9 * sin( st.x + uTime);
  float radius = snoise(vec3(st.x * 50.0 - uTime * 0.3, st.y * 18.0 - uTime * 0.3 , uTime * 0.1)) * 0.05;
  st.x -= cos(angle) * radius * 0.2;
  st.y += sin(angle) * radius * 0.5;


  vec4 color = texture2D(uTex, st);
  gl_FragColor = color;
}
`

