function draw() {
	let ms = millis()
	let delta = ms - lastTime
	lastTime = ms
	timeCircle += delta / 15000

	lines.update(delta)
	theShader.setUniform('uTime', ms / 1000)
	theShader.setUniform('uTex', g)

	noStroke()
	fill(0)
	shader(theShader)
	circle(0, 0, rSize)

	let cx = easing.outSine(timeCircle)
